/**
 * How the math allow-list is generated (EXP-049): the candidates whose samples KaTeX parses in
 * strict mode, sorted, with KaTeX's version and a SHA-256 fingerprint of the list. Shared by the
 * generator script and the test that checks the generated file is current.
 */
import { sha256Hex } from '@docedit/model';
import { CANDIDATES, ENVIRONMENT_CANDIDATES, environmentSample, sample } from './candidates.ts';
import { KATEX_VERSION, katexRejects } from './katex.ts';

/** The version of the allow-list format and policy; raise it when the rules of the gate change. */
export const ALLOW_LIST_VERSION = 1;

export interface AllowListData {
  version: number;
  katex: string;
  fingerprint: string;
  commands: Array<{ name: string; arity: string }>;
  environments: string[];
  /** Candidates KaTeX refused, with its message, for review. */
  refused: Array<{ name: string; reason: string }>;
}

export async function computeAllowList(): Promise<AllowListData> {
  const commands: Array<{ name: string; arity: string }> = [];
  const refused: Array<{ name: string; reason: string }> = [];
  const seen = new Set<string>();
  for (const c of CANDIDATES) {
    if (seen.has(c.name)) continue;
    seen.add(c.name);
    const reason = katexRejects(sample(c), true);
    if (reason === null) commands.push({ name: c.name, arity: c.arity });
    else refused.push({ name: c.name, reason });
  }
  commands.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  refused.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const environments = ENVIRONMENT_CANDIDATES.filter(
    (e) => katexRejects(environmentSample(e), true) === null,
  ).sort();
  const fingerprint = await sha256Hex(
    JSON.stringify({ version: ALLOW_LIST_VERSION, commands, environments }),
  );
  return {
    version: ALLOW_LIST_VERSION,
    katex: KATEX_VERSION,
    fingerprint,
    commands,
    environments,
    refused,
  };
}

export async function renderAllowList(): Promise<string> {
  const d = await computeAllowList();
  const lines = [
    '/**',
    ' * The math allow-list (09 §6.3; EXP-049). GENERATED by scripts/math-allow-list.ts from',
    ' * candidates.ts: do not edit. A candidate is listed when KaTeX parses its sample in strict mode.',
    ' */',
    `export const ALLOW_LIST = {`,
    `  version: ${d.version},`,
    `  katex: ${JSON.stringify(d.katex)},`,
    `  fingerprint: ${JSON.stringify(d.fingerprint)},`,
    `  commands: {`,
    ...d.commands.map((c) => `    ${JSON.stringify(c.name)}: ${JSON.stringify(c.arity)},`),
    `  },`,
    `  environments: [${d.environments.map((e) => JSON.stringify(e)).join(', ')}],`,
    `  refused: [`,
    ...d.refused.map((r) => `    ${JSON.stringify(r)},`),
    `  ],`,
    `} as const;`,
    '',
  ];
  return lines.join('\n');
}
